INSERT INTO enrollment_subjects (enrollment_id, subject_id)
SELECT e.id, x.subject_id FROM enrollments e JOIN strand_subjects x ON x.strand_id = e.strand_id AND x.grade_level = e.grade_level
WHERE e.id > @e0 AND e.id <= @e0 + 40 AND @go = 1;

-- where each student is now (the summary kept on the student's row)
UPDATE students s JOIN enrollments e ON e.student_id = s.id AND e.id > @e0 AND e.id <= @e0 + 40
SET s.grade_level = e.grade_level, s.track_id = e.track_id, s.strand_id = e.strand_id, s.section_id = e.section_id, s.updated_at_utc = @now
WHERE s.id > 0 AND @go = 1;

-- ================================================================ 2) The courses of the teachers (one teacher for each course of each section)
INSERT INTO teaching_assignments (id, teacher_id, section_id, subject_id, created_at_utc, updated_at_utc)
SELECT * FROM (
  SELECT @ta0 + 1 AS id, @t_0 AS teacher_id, @sec_BUSSENT_11_A AS section_id, @sub_0 AS subject_id, (@day0 + INTERVAL -38 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE) AS created_at_utc, (@day0 + INTERVAL -38 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE) AS updated_at_utc
