-- ================================================================ 5) Attendance of the last two weeks (school days only)
INSERT INTO attendance_records (assignment_id, student_id, attended_on, status, note, created_at_utc, updated_at_utc)
SELECT a.id, e.student_id, d.day,
  CASE WHEN e.student_id IN (@s_3, @s_26) THEN CASE WHEN MOD(CRC32(CONCAT(a.id, '-', e.student_id, '-', d.day)), 100) < 45 THEN 'Absent' WHEN MOD(CRC32(CONCAT(a.id, '-', e.student_id, '-', d.day)), 100) < 60 THEN 'Late' ELSE 'Present' END
       ELSE CASE WHEN MOD(CRC32(CONCAT(a.id, '-', e.student_id, '-', d.day)), 100) < 3 THEN 'Absent' WHEN MOD(CRC32(CONCAT(a.id, '-', e.student_id, '-', d.day)), 100) < 9 THEN 'Late' ELSE 'Present' END END,
  NULL, TIMESTAMP(d.day, '17:00:00'), TIMESTAMP(d.day, '17:00:00')
FROM teaching_assignments a
JOIN enrollments e ON e.section_id = a.section_id AND e.id > @e0 AND e.id <= @e0 + 40
JOIN (SELECT DATE_SUB(CURDATE(), INTERVAL n DAY) AS day FROM (SELECT 1 AS n UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9 UNION ALL SELECT 10 UNION ALL SELECT 11 UNION ALL SELECT 12 UNION ALL SELECT 13 UNION ALL SELECT 14) nn) d ON WEEKDAY(d.day) < 5
WHERE a.id > @ta0 AND a.id <= @ta0 + 77 AND @go = 1;

-- ================================================================ 6) Announcements, messages and notifications
INSERT INTO announcements (author_user_id, title, body, audience, category, section_id, assignment_id, expires_on, created_at_utc, updated_at_utc)
SELECT * FROM (
  SELECT @u_coord AS author_user_id, 'Welcome to the new school year' AS title, 'Classes are on. Please check your courses, open your modules and read the syllabus of each one. If something is missing, write to your teacher.' AS body, 'Everyone' AS audience, 'Other' AS category, NULL AS section_id, NULL AS assignment_id, NULL AS expires_on, (@day0 + INTERVAL -35 DAY + INTERVAL 1 HOUR + INTERVAL 0 MINUTE) AS created_at_utc, (@day0 + INTERVAL -35 DAY + INTERVAL 1 HOUR + INTERVAL 0 MINUTE) AS updated_at_utc
  UNION ALL SELECT @u_coord, 'Quiz week starts next Monday', 'Quizzes of all courses are open from Monday to Friday. Read the instructions first: some quizzes watch if you leave the page.', 'Students', 'Exam', NULL, NULL, DATE_ADD(CURDATE(), INTERVAL 10 DAY), (@day0 + INTERVAL -2 DAY + INTERVAL 2 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -2 DAY + INTERVAL 2 HOUR + INTERVAL 0 MINUTE)
  UNION ALL SELECT @u_coord, 'Faculty meeting on Friday, 3:00 PM', 'We will talk about the grades of the first term and the teacher evaluation. Please bring the grades of your courses.', 'Teachers', 'TeachersMeeting', NULL, NULL, DATE_ADD(CURDATE(), INTERVAL 4 DAY), (@day0 + INTERVAL -1 DAY + INTERVAL 3 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -1 DAY + INTERVAL 3 HOUR + INTERVAL 0 MINUTE)
  UNION ALL SELECT @u_coord, 'No classes on Monday', 'Monday is a holiday. Classes continue on Tuesday. Enjoy the long weekend and finish your activities before you rest.', 'Everyone', 'Holiday', NULL, NULL, DATE_ADD(CURDATE(), INTERVAL 6 DAY), (@day0 + INTERVAL -1 DAY + INTERVAL 5 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -1 DAY + INTERVAL 5 HOUR + INTERVAL 0 MINUTE)
  UNION ALL SELECT @u_coord, 'Semester break', 'The semester break starts after the last exam of the 1st term. The 2nd term starts on Monday, November 2.', 'Everyone', 'SemesterBreak', NULL, NULL, DATE_ADD(CURDATE(), INTERVAL 20 DAY), (@day0 + INTERVAL -3 DAY + INTERVAL 2 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -3 DAY + INTERVAL 2 HOUR + INTERVAL 0 MINUTE)
  UNION ALL SELECT @tu_0, 'Bring your calculators', 'For the activity next week please bring a calculator. We will practice the journal and the ledger.', 'Students', 'Other', @sec_BUSSENT_11_A, @ta0 + 1, DATE_ADD(CURDATE(), INTERVAL 7 DAY), (@day0 + INTERVAL -1 DAY + INTERVAL 4 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -1 DAY + INTERVAL 4 HOUR + INTERVAL 0 MINUTE)
  UNION ALL SELECT @tu_0, 'Quiz 1 is on Wednesday', 'Quiz 1 of Business Accounting covers Modules 1 and 2. It has 3 questions and 15 minutes.', 'Students', 'Exam', @sec_BUSSENT_11_A, @ta0 + 1, DATE_ADD(CURDATE(), INTERVAL 3 DAY), (@day0 + INTERVAL -1 DAY + INTERVAL 6 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -1 DAY + INTERVAL 6 HOUR + INTERVAL 0 MINUTE)
) AS r WHERE @go = 1;

INSERT INTO messages (sender_user_id, recipient_user_id, body, read_at_utc, created_at_utc, updated_at_utc)
SELECT * FROM (
  SELECT @su_1 AS sender_user_id, @tu_0 AS recipient_user_id, 'Good morning sir. When is Activity 2 due?' AS body, (@day0 + INTERVAL -2 DAY + INTERVAL 3 HOUR + INTERVAL 0 MINUTE) AS read_at_utc, (@day0 + INTERVAL -2 DAY + INTERVAL 1 HOUR + INTERVAL 0 MINUTE) AS created_at_utc, (@day0 + INTERVAL -2 DAY + INTERVAL 1 HOUR + INTERVAL 0 MINUTE) AS updated_at_utc
  UNION ALL SELECT @tu_0, @su_1, 'Good morning Juan. It is due this week. You can see the exact date in your calendar.', (@day0 + INTERVAL -2 DAY + INTERVAL 4 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -2 DAY + INTERVAL 3 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -2 DAY + INTERVAL 3 HOUR + INTERVAL 0 MINUTE)
  UNION ALL SELECT @su_1, @tu_0, 'Thank you sir!', (@day0 + INTERVAL -2 DAY + INTERVAL 5 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -2 DAY + INTERVAL 4 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -2 DAY + INTERVAL 4 HOUR + INTERVAL 0 MINUTE)
  UNION ALL SELECT @su_2, @tu_0, 'Sir, may I send my worksheet tomorrow? I was not feeling well.', NULL, (@day0 + INTERVAL 0 DAY + INTERVAL 1 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL 0 DAY + INTERVAL 1 HOUR + INTERVAL 0 MINUTE)
  UNION ALL SELECT @u_prov, @tu_0, 'Please check the syllabus I sent you for Business Accounting. It is a draft: change what you need and post it.', (@day0 + INTERVAL -1 DAY + INTERVAL 6 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -1 DAY + INTERVAL 5 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -1 DAY + INTERVAL 5 HOUR + INTERVAL 0 MINUTE)
  UNION ALL SELECT @tu_0, @u_prov, 'Received, thank you. I will post it on Monday.', NULL, (@day0 + INTERVAL -1 DAY + INTERVAL 7 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -1 DAY + INTERVAL 7 HOUR + INTERVAL 0 MINUTE)
  UNION ALL SELECT @u_prov, @tu_3, 'Good morning sir. Did you see Module 5 I sent for Effective Communication? It is a draft waiting for you.', NULL, (@day0 + INTERVAL -1 DAY + INTERVAL 2 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -1 DAY + INTERVAL 2 HOUR + INTERVAL 0 MINUTE)
  UNION ALL SELECT @su_3, @tu_1, 'Sir, I was absent last week. May I take the quiz again?', NULL, (@day0 + INTERVAL 0 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL 0 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE)
  UNION ALL SELECT @u_guidance, @su_3, 'Hello Carlo. Let us talk about how school is going. You can come to the guidance office any afternoon.', NULL, (@day0 + INTERVAL -1 DAY + INTERVAL 2 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -1 DAY + INTERVAL 2 HOUR + INTERVAL 0 MINUTE)
  UNION ALL SELECT @tu_1, @tu_2, 'Are you free after the meeting? I want to share the review materials.', (@day0 + INTERVAL -3 DAY + INTERVAL 6 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -3 DAY + INTERVAL 5 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -3 DAY + INTERVAL 5 HOUR + INTERVAL 0 MINUTE)
) AS r WHERE @go = 1;

