INSERT INTO stored_file_contents (file_id, data)
SELECT * FROM (
  SELECT @sf0 + 1 AS file_id, CAST('Accounting reviewer

1. Assets = Liabilities + Equity
2. Debit left, credit right
3. Journal first, then the ledger, then the trial balance.
' AS BINARY) AS data
  UNION ALL SELECT @sf0 + 2, CAST('Day,Subject,Time
Monday,Accounting,4:00 PM
Wednesday,Mathematics,4:00 PM
Friday,Review,4:00 PM
' AS BINARY)
  UNION ALL SELECT @sf0 + 3, CAST('Business Accounting - Grade 11

Weeks 1-4: the accounting equation, journal and ledger.
Weeks 5-8: trial balance and financial statements.
Grades: activities 30%, quizzes 30%, task performance 40%.
' AS BINARY)
  UNION ALL SELECT @sf0 + 4, CAST('Planning for the term

- Post the modules of the second half of the term.
- Send the grades before the faculty meeting.
- Review the attendance of students who miss class.
' AS BINARY)
  UNION ALL SELECT @sf0 + 5, CAST('Notes on journals

A journal entry has a date, the accounts, the debit and the credit, and a short explanation.
' AS BINARY)
) AS r WHERE @go = 1;

