  SELECT @eq0 + 1 AS id, @ev0 + 1 AS evaluation_id, 1 AS position, 'The teacher explains the lessons clearly.' AS text, 'Likert' AS kind, NULL AS options_text, 'Teaching' AS category, (@day0 + INTERVAL -8 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE) AS created_at_utc, (@day0 + INTERVAL -8 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE) AS updated_at_utc
  UNION ALL SELECT @eq0 + 2, @ev0 + 1, 2, 'The teacher is prepared for every class.', 'Likert', NULL, 'Preparation', (@day0 + INTERVAL -8 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -8 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE)
  UNION ALL SELECT @eq0 + 3, @ev0 + 1, 3, 'The teacher keeps the class orderly and respectful.', 'Likert', NULL, 'Classroom management', (@day0 + INTERVAL -8 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -8 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE)
  UNION ALL SELECT @eq0 + 4, @ev0 + 1, 4, 'How often does the teacher answer questions and give feedback on time?', 'Frequency', NULL, 'Communication', (@day0 + INTERVAL -8 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -8 DAY + INTERVAL 0 HOUR + INTERVAL 0 MINUTE)
