INSERT INTO notifications (user_id, kind, title, body, link, is_read, created_at_utc, updated_at_utc)
SELECT * FROM (
  SELECT @su_1 AS user_id, 'evaluation' AS kind, 'Please evaluate your teachers' AS title, 'Teacher evaluation - first term. Your answers are anonymous. Due in 8 days.' AS body, 'student/evaluations' AS link, 0 AS is_read, (@day0 + INTERVAL -6 DAY + INTERVAL 1 HOUR + INTERVAL 0 MINUTE) AS created_at_utc, (@day0 + INTERVAL -6 DAY + INTERVAL 1 HOUR + INTERVAL 0 MINUTE) AS updated_at_utc
  UNION ALL SELECT @su_2, 'evaluation', 'Please evaluate your teachers', 'Teacher evaluation - first term. Your answers are anonymous. Due in 8 days.', 'student/evaluations', 1, (@day0 + INTERVAL -6 DAY + INTERVAL 1 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -6 DAY + INTERVAL 1 HOUR + INTERVAL 0 MINUTE)
) AS r WHERE @go = 1;

-- ================================================================ 11) Guidance referrals (the system makes the other ones by itself from the grades and the attendance)
INSERT INTO referrals (student_id, assignment_id, reason, detail, metric, status, intervention, notes, outcome, resolved_at_utc, handled_by_user_id, created_at_utc, updated_at_utc)
SELECT * FROM (
  SELECT @s_3 AS student_id, @ta0 + 1 AS assignment_id, 'FailingGrades' AS reason, 'BUSINESS ACCOUNTING: 58% (passing is 70)' AS detail, 58.00 AS metric, 'InProgress' AS status, 'Talked with the student' AS intervention, 'Carlo has been absent a lot. We agreed on tutoring after class and a call to the parents.' AS notes, NULL AS outcome, NULL AS resolved_at_utc, @u_guidance AS handled_by_user_id, (@day0 + INTERVAL -9 DAY + INTERVAL 2 HOUR + INTERVAL 0 MINUTE) AS created_at_utc, (@day0 + INTERVAL -1 DAY + INTERVAL 3 HOUR + INTERVAL 0 MINUTE) AS updated_at_utc
  UNION ALL SELECT @s_6, NULL, 'LowAttendance', 'Absent in 4 of the last 10 classes', 60.00, 'Resolved', 'Parents called', 'Kristine was sick; the family sent a medical certificate. Attendance is normal again.', 'Improved', (@day0 + INTERVAL -12 DAY + INTERVAL 4 HOUR + INTERVAL 0 MINUTE), @u_guidance, (@day0 + INTERVAL -30 DAY + INTERVAL 2 HOUR + INTERVAL 0 MINUTE), (@day0 + INTERVAL -12 DAY + INTERVAL 4 HOUR + INTERVAL 0 MINUTE)
) AS r WHERE @go = 1;

-- ================================================================ What was added
SELECT CASE WHEN @go = 1 THEN 'Done: the sample data was added.' WHEN @found = 0 THEN 'Nothing was added: some of the sample people or places were not found. Run seaittlms_reset_and_rebuild.sql and then seaittlms_sample_accounts.sql first.' ELSE 'Nothing was added: the sample students are already enrolled (this file runs once).' END AS result;
SELECT 'enrollments' AS table_name, COUNT(*) AS `rows` FROM enrollments
UNION ALL SELECT 'teaching_assignments', COUNT(*) FROM teaching_assignments
UNION ALL SELECT 'course_schedules', COUNT(*) FROM course_schedules
UNION ALL SELECT 'modules', COUNT(*) FROM modules
UNION ALL SELECT 'module_items', COUNT(*) FROM module_items
UNION ALL SELECT 'quiz_questions', COUNT(*) FROM quiz_questions
UNION ALL SELECT 'module_views', COUNT(*) FROM module_views
UNION ALL SELECT 'item_views', COUNT(*) FROM item_views
UNION ALL SELECT 'submissions', COUNT(*) FROM submissions
UNION ALL SELECT 'attendance_records', COUNT(*) FROM attendance_records
UNION ALL SELECT 'announcements', COUNT(*) FROM announcements
UNION ALL SELECT 'messages', COUNT(*) FROM messages
UNION ALL SELECT 'notifications', COUNT(*) FROM notifications
